function aplicarMascaras(){var e=(e,a)=>{document.querySelectorAll(e).forEach(e=>{e.addEventListener("input",e=>a(e.target))})};e('input[name*="cpf"], #cpf, #cpf-doador',e=>{let a=e.value.replace(/\D/g,"").substring(0,11);a=(a=(a=a.replace(/(\d{3})(\d)/,"$1.$2")).replace(/(\d{3})(\d)/,"$1.$2")).replace(/(\d{3})(\d{1,2})$/,"$1-$2"),e.value=a}),e('input[name*="telefone"]',e=>{let a=e.value.replace(/\D/g,"").substring(0,11);a=(a=a.replace(/(\d{2})(\d)/,"($1) $2")).replace(/(\d{5})(\d)/,"$1-$2"),e.value=a}),e('input[name*="cep"]',e=>{let a=e.value.replace(/\D/g,"").substring(0,8);a=a.replace(/(\d{5})(\d)/,"$1-$2"),e.value=a})}function validarEmail(e){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}export{aplicarMascaras,validarEmail};